      WHEN date_utc BETWEEN DATE '2023-10-01' AND DATE '2026-07-31' AND REGEXP_CONTAINS(mention_context, r'(^|[^a-z0-9])vegas\s+golden\s+knights([^a-z0-9]|$)') THEN 'VGK-current'
      WHEN date_utc BETWEEN DATE '2023-10-01' AND DATE '2026-07-31' AND REGEXP_CONTAINS(mention_context, r'(^|[^a-z0-9])winnipeg\s+jets([^a-z0-9]|$)') THEN 'WPG-current'
      WHEN date_utc BETWEEN DATE '2023-10-01' AND DATE '2026-07-31' AND REGEXP_CONTAINS(mention_context, r'(^|[^a-z0-9])washington\s+capitals([^a-z0-9]|$)') THEN 'WSH-current'
      ELSE NULL
    END AS mapping_id,
    date_utc,
    url
  FROM candidate_ngrams
),
matched_urls AS (
  SELECT mapping_id, date_utc, url
  FROM tagged_mentions
  WHERE mapping_id IS NOT NULL
  GROUP BY mapping_id, date_utc, url
),
daily_counts AS (
  SELECT mapping_id, date_utc, COUNT(DISTINCT url) AS article_count
  FROM matched_urls
  GROUP BY mapping_id, date_utc
),
date_spine AS (
  SELECT mapping.mapping_id, mapping.club_id, mapping.entity_id,
         mapping.entity_label, day AS date_utc
  FROM mappings AS mapping,
       UNNEST(GENERATE_DATE_ARRAY(mapping.valid_from, mapping.valid_to)) AS day
)
SELECT
  spine.mapping_id,
  spine.club_id,
  spine.entity_id,
  spine.entity_label,
  spine.date_utc,
  COALESCE(counts.article_count, 0) AS article_count
FROM date_spine AS spine
LEFT JOIN daily_counts AS counts
  USING (mapping_id, date_utc)
ORDER BY club_id, mapping_id, date_utc;
